// Tensor-core FlashAttention forward (sm_86): wmma m16n16k16 bf16, 4 warps,
// BLOCK_M=64 query rows, BLOCK_N=64 keys per tile, online softmax in the
// exp2 domain, GQA support. BF16 in/out, FP32 accumulation.
//
// Work partitioning: one block per (query tile, batch*head). Warp w owns
// query rows [16w, 16w+16) via 8 wmma A fragments (16x16x16 row-major,
// ldm 128). K/V tiles are staged in shared memory. Per K/V tile a warp does
// 8 QK mma -> 8 S accumulators (16 rows x 64 cols, 8 floats/lane), then
// per-lane online softmax (each lane owns rows {gid, gid+8} x cols
// {2*tig, 2*tig+1, 2*tig+8, 2*tig+9} in every 16-col group), then 32 PV mma
// accumulate O. The P fragment is assembled in place from the softmaxed S
// accumulator, whose layout matches the m16n16k16 matrix_a layout.

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_bf16.h>
#include <mma.h>
#include <math.h>

namespace {

constexpr int BLOCK_M = 64;   // query rows per block
constexpr int BLOCK_N = 64;   // key/value rows per tile
constexpr int HEAD_DIM = 128;
constexpr int NUM_WARPS = 4;
constexpr int NUM_THREADS = NUM_WARPS * 32;
constexpr float LOG2E = 1.4426950408889634f;
constexpr float NEG_INF = -INFINITY;

using namespace nvcuda;

__device__ __forceinline__ float exp2_approx(float x) {
    float y;
    asm("ex2.approx.f32 %0, %1;" : "=f"(y) : "f"(x));
    return y;
}

__device__ __forceinline__ uint32_t pack2bf16(float lo, float hi) {
    union { __nv_bfloat16 h[2]; uint32_t u; } v;
    v.h[0] = __float2bfloat16(lo);
    v.h[1] = __float2bfloat16(hi);
    return v.u;
}

// Forward declaration (defined after the kernel to keep the hot loop first).
torch::Tensor attention_forward(torch::Tensor q, torch::Tensor k,
                                torch::Tensor v, bool causal);

}  // namespace

// Tensor-core FlashAttention forward (sm_86): wmma m16n16k16 bf16, 4 warps,
// BLOCK_M=64 query rows, BLOCK_N=64 keys per tile, online softmax in the
// exp2 domain, GQA support. BF16 in/out, FP32 accumulation.
//
// Work partitioning: one block per (query tile, batch*head). Warp w owns
// query rows [16w, 16w+16) via 8 wmma A fragments (16x16x16 row-major,
// ldm 128). K/V tiles are staged in shared memory. Per K/V tile a warp does
// 8 QK mma -> 8 S accumulators (16 rows x 64 cols, 8 floats/lane), then
// per-lane online softmax (each lane owns rows {gid, gid+8} x cols
// {2*tig, 2*tig+1, 2*tig+8, 2*tig+9} in every 16-col group), then 32 PV mma
// accumulate O. The P fragment is assembled in place from the softmaxed S
// accumulator, whose layout matches the m16n16k16 matrix_a layout.

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_bf16.h>
#include <mma.h>
#include <math.h>

namespace {

constexpr int BLOCK_M = 64;   // query rows per block
constexpr int BLOCK_N = 64;   // key/value rows per tile
constexpr int HEAD_DIM = 128;
constexpr int NUM_WARPS = 4;
constexpr int NUM_THREADS = NUM_WARPS * 32;
constexpr float LOG2E = 1.4426950408889634f;
constexpr float NEG_INF = -INFINITY;

using namespace nvcuda;

__device__ __forceinline__ float exp2_approx(float x) {
    float y;
    asm("ex2.approx.f32 %0, %1;" : "=f"(y) : "f"(x));
    return y;
}

__device__ __forceinline__ uint32_t pack2bf16(float lo, float hi) {
    union { __nv_bfloat16 h[2]; uint32_t u; } v;
    v.h[0] = __float2bfloat16(lo);
    v.h[1] = __float2bfloat16(hi);
    return v.u;
}

// Forward declaration (defined after the kernel to keep the hot loop first).
torch::Tensor attention_forward(torch::Tensor q, torch::Tensor k,
                                torch::Tensor v, bool causal);

}  // namespace

