__global__ void __launch_bounds__(NUM_THREADS, 2) attention_fwd_kernel(
    const __nv_bfloat16* __restrict__ q,
    const __nv_bfloat16* __restrict__ k,
    const __nv_bfloat16* __restrict__ v,
    __nv_bfloat16* __restrict__ out,
    int seq_len, float scale_log2, bool causal, int q_per_kv)
{
    __shared__ __nv_bfloat16 sK[BLOCK_N][HEAD_DIM];
    __shared__ __nv_bfloat16 sV[BLOCK_N][HEAD_DIM];

    const int m_tile = blockIdx.x;
    const int bh = blockIdx.y;
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    const int gid = lane / 4, tig = lane % 4;

    const long long base = (long long)bh * seq_len * HEAD_DIM;
    const long long base_kv = (long long)(bh / q_per_kv) * seq_len * HEAD_DIM;
    const int grow0 = m_tile * BLOCK_M + warp * 16;

    // Q: 8 A-fragments (16 rows x 16 dims each), row-major ldm 128.
    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> qf[8];
#pragma unroll
    for (int j = 0; j < 8; ++j)
        wmma::load_matrix_sync(qf[j], q + base + (long long)grow0 * HEAD_DIM + j * 16,
                               HEAD_DIM);

    // O accumulators (8 head-dim halves of 16).
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc_o[8];
#pragma unroll
    for (int j = 0; j < 8; ++j) wmma::fill_fragment(acc_o[j], 0.0f);

    // Online softmax state in exp2 domain, per row (rows gid and gid+8).
    float m2[2] = {NEG_INF, NEG_INF}, l[2] = {0.f, 0.f};

    const int row_hi = min(m_tile * BLOCK_M + BLOCK_M - 1, seq_len - 1);
    int n_tiles = (seq_len + BLOCK_N - 1) / BLOCK_N;
    if (causal) n_tiles = min(n_tiles, row_hi / BLOCK_N + 1);
    if (grow0 >= seq_len) n_tiles = 0;

    for (int nt = 0; nt < n_tiles; ++nt) {
        // Stage K/V tile into shared (16B units, zero-pad rows >= S).
        {
            const int nchunk = BLOCK_N * HEAD_DIM / 8;
            const uint4 zero = make_uint4(0, 0, 0, 0);
            for (int i = threadIdx.x; i < nchunk; i += NUM_THREADS) {
                const int r = i / 16, u = i % 16;
                const int grow_kv = nt * BLOCK_N + r;
                if (grow_kv < seq_len) {
                    *reinterpret_cast<uint4*>(&sK[r][u * 8]) =
                        *reinterpret_cast<const uint4*>(
                            k + base_kv + (long long)grow_kv * HEAD_DIM + u * 8);
                    *reinterpret_cast<uint4*>(&sV[r][u * 8]) =
                        *reinterpret_cast<const uint4*>(
                            v + base_kv + (long long)grow_kv * HEAD_DIM + u * 8);
                } else {
                    *reinterpret_cast<uint4*>(&sK[r][u * 8]) = zero;
                    *reinterpret_cast<uint4*>(&sV[r][u * 8]) = zero;
                }
            }
        }
        __syncthreads();

        // ---- QK: 8 mma per warp -> S accumulators (16x64, 4 floats/lane) ----
        wmma::fragment<wmma::accumulator, 16, 16, 16, float> s_acc[8];
#pragma unroll
        for (int j = 0; j < 8; ++j) wmma::fill_fragment(s_acc[j], 0.0f);
#pragma unroll
        for (int j = 0; j < 8; ++j) {
            wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::col_major> kf;
            wmma::load_matrix_sync(kf, &sK[0][j * 16], HEAD_DIM);
            wmma::mma_sync(s_acc[j], qf[j], kf, s_acc[j]);
        }
        // s_acc[j] is the 16x16 score block (rows x cols {j*16..j*16+16}).
        // Each lane holds 4 values: rows {gid, gid+8} x cols
        // {2*tig, 2*tig+1} (even j) or {2*tig+8, 2*tig+9} (odd j).

        // ---- Online softmax (exp2 domain), tile granularity ----
#pragma unroll
        for (int k = 0; k < 4; ++k) {
            const int j = (k < 2) ? 0 : 1;         // which 16-col group
            const int cbase = j * 16 + (k % 2) * 8 + 2 * tig;  // col
            const float s0 = s_acc[j].x[k * 2 + 0] * scale_log2;
            const float s1 = s_acc[j].x[k * 2 + 1] * scale_log2;
#pragma unroll
            for (int r = 0; r < 2; ++r) {
                const int grow = grow0 + gid + r * 8;
                const int gcol = nt * BLOCK_N + cbase;
                const bool skip = gcol >= seq_len || (causal && gcol > grow);
                const float m_new = skip ? m2[r] : fmaxf(m2[r], fmaxf(s0, s1));
                const float corr = exp2_approx(m2[r] - m_new);
                const float p0 = skip ? 0.f : exp2_approx(s0 - m_new);
                const float p1 = skip ? 0.f : exp2_approx(s1 - m_new);
                l[r] = l[r] * corr + p0 + p1;
                m2[r] = m_new;
                s_acc[j].x[k * 2 + 0] = p0;
                s_acc[j].x[k * 2 + 1] = p1;
            }
        }

        // ---- PV: accumulate O += P * V ----
#pragma unroll
        for (int t = 0; t < 2; ++t) {
            wmma::fragment<wmma::accumulator, 16, 16, 16, float> p_acc;
#pragma unroll
            for (int j = 0; j < 8; ++j) {
                wmma::load_matrix_sync(p_acc, &s_acc[j].x[t * 4], 8, wmma::mem_row_major);
                wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::col_major> vf;
                wmma::load_matrix_sync(vf, &sV[0][t * 16 + j * 2], HEAD_DIM);
                wmma::mma_sync(acc_o[j], p_acc, vf, acc_o[j]);
            }
        }
        __syncthreads();
    }

    // ---- Write out ----
    const int grow = grow0 + gid;
    if (grow < seq_len) {
        const float inv = (l[0] > 0.f) ? 1.f / l[0] : 0.f;
#pragma unroll
        for (int j = 0; j < 8; ++j) {
            const float o0 = acc_o[j].x[0 * 4 + tig] * inv;
            const float o1 = acc_o[j].x[1 * 4 + tig] * inv;
            const float o2 = acc_o[j].x[2 * 4 + tig] * inv;
            const float o3 = acc_o[j].x[3 * 4 + tig] * inv;
            *reinterpret_cast<uint4*>(out + base + (long long)grow * HEAD_DIM + j * 16 + tig * 4)
                = make_uint4(pack2bf16(o0, o1), pack2bf16(o2, o3), 0, 0);
        }
    }
