// Probe: recover wmma m16n16k16 bf16 A-fragment and C-accumulator layouts.
#include <cuda_bf16.h>
#include <mma.h>
#include <cstdio>
using namespace nvcuda;

__global__ void probe(__nv_bfloat16* out_a, float* out_c) {
    __shared__ __nv_bfloat16 sA[16][16];
    __shared__ __nv_bfloat16 sB[16][16];
    int tid = threadIdx.x;
    for (int i = tid; i < 256; i += 32) {
        sA[i/16][i%16] = __float2bfloat16(1000.f + (i/16)*16 + (i%16));
        sB[i/16][i%16] = (i/16 == i%16) ? __float2bfloat16(1.f) : __float2bfloat16(0.f);
    }
    __syncthreads();
    int lane = threadIdx.x % 32;
    wmma::fragment<wmma::matrix_a, 16,16,16, __nv_bfloat16, wmma::row_major> af;
    wmma::load_matrix_sync(af, &sA[0][0], 16);
    wmma::fragment<wmma::matrix_b, 16,16,16, __nv_bfloat16, wmma::col_major> bf;
    wmma::load_matrix_sync(bf, &sB[0][0], 16);
    wmma::fragment<wmma::accumulator, 16,16,16, float> cf;
    wmma::fill_fragment(cf, 0.f);
    wmma::mma_sync(cf, af, bf, cf);
    for (int e = 0; e < 8; ++e) { out_a[lane*8+e] = af.x[e]; out_c[lane*8+e] = cf.x[e]; }
}

int main() {
    __nv_bfloat16* out_a; float* out_c;
    cudaMalloc(&out_a, 32*8*2); cudaMalloc(&out_c, 32*8*4);
    probe<<<1,32>>>(out_a, out_c);
    cudaDeviceSynchronize();
    __nv_bfloat16* ha = new __nv_bfloat16[256]; float* hc = new float[256];
    cudaMemcpy(ha, out_a, 256*2, cudaMemcpyDeviceToHost);
    cudaMemcpy(hc, out_c, 256*4, cudaMemcpyDeviceToHost);
    printf("A fragment: lane e -> value (=1000+r*16+c means (r,c))\n");
    for (int l = 0; l < 32; ++l) {
        printf("lane %2d:", l);
        for (int e = 0; e < 8; ++e) printf(" %5.0f", (float)ha[l*8+e]);
        printf("\n");
    }
    printf("C accumulator (B=identity so C=A):\n");
    for (int l = 0; l < 32; ++l) {
        printf("lane %2d:", l);
        for (int e = 0; e < 8; ++e) printf(" %5.0f", hc[l*8+e]);
        printf("\n");
    }
    return 0;
}

