    for (int i = tid; i < 256; i += 32) {
        sA[i/16][i%16] = __float2half(1000.f + (i/16)*16 + (i%16));
        sB[i/16][i%16] = (i/16 == i%16) ? __float2half(1.f) : __float2half(0.f);
    }
    __syncthreads();
    int lane = threadIdx.x % 32;
    wmma::fragment<wmma::matrix_a, 16,16,16, __half, wmma::row_major> af;
    wmma::load_matrix_sync(af, &sA[0][0], 16);
    wmma::fragment<wmma::matrix_b, 16,16,16, __half, wmma::col_major> bf;
    wmma::load_matrix_sync(bf, &sB[0][0], 16);
    wmma::fragment<wmma::accumulator, 16,16,16, float> cf;
    wmma::fill_fragment(cf, 0.f);
    wmma::mma_sync(cf, af, bf, cf);
    for (int e = 0; e < 8; ++e) { out_a[lane*8+e] = af.x[e]; out_c[lane*8+e] = cf.x[e]; }
}

int main() {
    __half* out_a; float* out_c;
    cudaMalloc(&out_a, 32*8*2); cudaMalloc(&out_c, 32*8*4);
    probe<<<1,32>>>(out_a, out_c);
    cudaDeviceSynchronize();
    __half* ha = new __half[256]; float* hc = new float[256];
    cudaMemcpy(ha, out_a, 256*2, cudaMemcpyDeviceToHost);
    cudaMemcpy(hc, out_c, 256*4, cudaMemcpyDeviceToHost);
    printf("A fragment: lane e -> value (=1000+r*16+c means (r,c))\n");
    for (int l = 0; l < 32; ++l) {
        printf("lane %2d:", l);
        for (int e = 0; e < 8; ++e) printf(" %5.0f", (float)ha[l*8+e]);
        printf("\n");
    }
    printf("C accumulator (B=identity so C=A):\n");
    for (int l = 0; l < 32; ++l) {
        printf("lane %2d:", l);
        for (int e = 0; e < 8; ++e) printf(" %5.0f", hc[l*8+e]);
        printf("\n");
    }
    return 0;
}

