                }
                const float corr = exp2_approx(m2[r] - mx);
                m2[r] = mx;
                float lsum = 0.f;
#pragma unroll
                for (int e = 0; e < 4; ++e) {
                    const int gcol = cbase + (e < 2 ? e : 8 + e - 2);
                    const bool valid = gcol < seq_len && (!causal || gcol <= grow);
                    const float s = s_acc[j].x[2 * r + (e < 2 ? e : e + 2)];
                    const float pv = valid ? exp2_approx(s - mx) : 0.f;
                    p[e] = pv;
                    lsum += pv;
                }
                l[r] = l[r] * corr + lsum;
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    s_acc[j].x[2 * r + (e < 2 ? e : e + 2)] = p[e];
            }
        }

        // ---- PV: O += P * V (P converted to bf16 in place, same layout) ----
#pragma unroll
        for (int t = 0; t < 8; ++t) {
#pragma unroll
            for (int j = 0; j < 4; ++j) {
                wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> paf;
#pragma unroll
                for (int e = 0; e < 8; ++e) paf.x[e] = __float2bfloat16(s_acc[j].x[e]);
                wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::row_major> vf;
                wmma::load_matrix_sync(vf, &sV[j * 16][t * 16], HEAD_DIM);
                wmma::mma_sync(acc_o[t], paf, vf, acc_o[t]);
            }
        }
        __syncthreads();
    }

    // ---- Write out (row gid: x0,x1,x4,x5; row gid+8: x2,x3,x6,x7) ----
    {
        const int rowA = grow0 + gid, rowB = grow0 + gid + 8;
        if (rowA < seq_len) {
            const float inv = (l[0] > 0.f) ? 1.f / l[0] : 0.f;
#pragma unroll
            for (int j = 0; j < 8; ++j) {
                *reinterpret_cast<uint32_t*>(out + base + (long long)rowA * HEAD_DIM + j * 16 + 2 * tig)
                    = pack2bf16(acc_o[j].x[0] * inv, acc_o[j].x[1] * inv);
                *reinterpret_cast<uint32_t*>(out + base + (long long)rowA * HEAD_DIM + j * 16 + 2 * tig + 8)
                    = pack2bf16(acc_o[j].x[4] * inv, acc_o[j].x[5] * inv);
            }
        }
        if (rowB < seq_len) {
            const float inv = (l[1] > 0.f) ? 1.f / l[1] : 0.f;
#pragma unroll
            for (int j = 0; j < 8; ++j) {
                *reinterpret_cast<uint32_t*>(out + base + (long long)rowB * HEAD_DIM + j * 16 + 2 * tig)
                    = pack2bf16(acc_o[j].x[2] * inv, acc_o[j].x[3] * inv);
                *reinterpret_cast<uint32_t*>(out + base + (long long)rowB * HEAD_DIM + j * 16 + 2 * tig + 8)
                    = pack2bf16(acc_o[j].x[6] * inv, acc_o[j].x[7] * inv);
            }
        }
    }
}

}  // namespace

torch::Tensor attention_forward(torch::Tensor q, torch::Tensor k,
                                torch::Tensor v, bool causal)
{
    TORCH_CHECK(q.is_cuda() && k.is_cuda() && v.is_cuda(), "q/k/v must be CUDA tensors");
    TORCH_CHECK(q.scalar_type() == torch::kBFloat16 &&
                k.scalar_type() == torch::kBFloat16 &&
                v.scalar_type() == torch::kBFloat16, "q/k/v must be bfloat16");
    TORCH_CHECK(q.dim() == 4, "expected [B, H, S, D]");
    TORCH_CHECK(q.size(3) == HEAD_DIM, "head_dim must be ", HEAD_DIM);
    TORCH_CHECK(q.is_contiguous() && k.is_contiguous() && v.is_contiguous(),
                "q/k/v must be contiguous");

    const at::cuda::CUDAGuard guard(q.device());
    const int B = q.size(0), H = q.size(1), S = q.size(2);
    TORCH_CHECK((long long)B * H <= 65535, "B*H exceeds grid.y limit");

    const int kv_heads = k.size(1);
    TORCH_CHECK(H % kv_heads == 0, "heads must be divisible by kv_heads");
    const int q_per_kv = H / kv_heads;
    TORCH_CHECK(k.size(0) == B && v.size(0) == B &&
                k.size(1) == kv_heads && v.size(1) == kv_heads &&
                k.size(2) == S && v.size(2) == S, "shape mismatch");

    auto out = torch::empty_like(q);
    const float scale_log2 = LOG2E / sqrtf((float)HEAD_DIM);
    dim3 grid((S + BLOCK_M - 1) / BLOCK_M, B * H);

    attention_fwd_kernel<<<grid, NUM_THREADS, 0,
                           at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __nv_bfloat16*>(q.data_ptr()),
        reinterpret_cast<const __nv_bfloat16*>(k.data_ptr()),
        reinterpret_cast<const __nv_bfloat16*>(v.data_ptr()),
        reinterpret_cast<__nv_bfloat16*>(out.data_ptr()),
        S, scale_log2, causal, q_per_kv);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}

